def divide_all(xs: list[int], ys: list[int]) -> list[int]:
    result: list[int] = []
    for i, (a, b) in enumerate(zip(xs, ys)):
        if b == 0:
            raise ValueError(f"division by zero at index {i}")
        q = abs(a) // abs(b)
        result.append(q if (a < 0) == (b < 0) else -q)
    return result
